let report;
const $=selector=>document.querySelector(selector);
const escape=value=>String(value??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const names={random:'随机初始化',warmup:'共享热身模型',sft:'全参数 SFT',lora:'LoRA',chosen_sft:'chosen-only SFT',dpo:'DPO',dpo_anchor:'DPO + 辅助 SFT',simpo:'SimPO',ppo:'PPO',grpo:'GRPO',distill:'筛选与序列蒸馏'};
const number=(value,digits=4)=>Number.isFinite(value)?value.toFixed(digits):'—';
const gpuRun=()=>String(report?.environment?.device||'').startsWith('cuda');
const evidenceLabel=()=>gpuRun()?'GPU 实测':'历史 CPU 参考';
export function practicePage(){
 return `<div class="eyebrow">GPU POST-TRAINING PRACTICE</div><h1 class="lesson-title">在 GPU 上，把后训练跑起来。</h1><p class="lesson-intro">设备预检 → CUDA / FP32 训练 → 检查原始回答与资源开销。</p><div class="notice">浏览器不启动训练。下面的实际设备和精度从报告读取，历史 CPU 报告保留为独立参考。模型只有约 1.9 万参数，任务是复制符号；结果不代表大模型安全 benchmark，也不能用于算法排名。</div><div class="button-row" style="margin-bottom:26px"><a class="btn primary" href="./downloads/safeposttrain-tiny-lm.zip" download>下载 GPU 训练实战包 ↓</a><a class="btn" href="./content/tiny-lm-report.json" download>下载当前展示报告 ↓</a><a class="btn ghost" href="./content/tiny-lm-cpu-reference.json" download>历史 CPU 参考 ↓</a><a class="btn ghost" href="#/guide/study">学习顺序与练习</a></div><section class="prose-section"><h2>先检查设备，再启动训练</h2><p>在已安装 CUDA 版 PyTorch 的环境中，从项目根目录执行。默认选择 CUDA，不可用时直接报错，不自动回退 CPU。</p><pre class="practice-code">python -m labs.tiny_lm.run --check-device
python -m labs.tiny_lm.run --device cuda --final-eval --output artifacts/tiny-lm-cuda-seed7 --seed 7</pre><p>安装方式见 <a href="https://pytorch.org/get-started/locally/" target="_blank" rel="noopener noreferrer">PyTorch 官方选择器</a>。FP32 为当前精度；BF16、QLoRA 与多卡属于后续扩展。CPU 锁文件仅用于历史环境。</p></section><div id="practice-root"><p role="status">正在读取报告与实际设备…</p></div>`;
}
function lossChart(history){
 if(!history?.length)return '<p class="lab-note">该阶段没有优化步骤，用作对照起点。</p>';
 const width=560,height=160,pad=28,values=history.map(x=>x.loss_before_update),min=Math.min(...values),max=Math.max(...values),span=max-min||1,last=history.at(-1).step;
 const points=history.map(x=>`${pad+x.step/last*(width-pad*2)},${height-pad-(x.loss_before_update-min)/span*(height-pad*2)}`).join(' ');
 return `<svg viewBox="0 0 ${width} ${height}" class="plot" role="img" aria-label="${evidenceLabel()}：当前阶段 loss 随优化步变化"><line x1="${pad}" x2="${width-pad}" y1="${height-pad}" y2="${height-pad}" stroke="#cbd5c4"/><polyline points="${points}" fill="none" stroke="#315f43" stroke-width="2.5"/><text x="${pad}" y="15" fill="#6d786f" font-size="10">${number(max,3)}</text><text x="${pad}" y="${height-8}" fill="#6d786f" font-size="10">${number(min,3)}</text><text x="${width-100}" y="${height-8}" fill="#6d786f" font-size="10">${last} 次更新</text></svg><p class="lab-note">${evidenceLabel()} · 点是更新前记录的训练 loss。各方法的目标和量纲不同，这张曲线只用于观察当前阶段。</p>`;
}
function resultHTML(){
 const stage=report.stages.find(x=>x.name===$('#practice-method').value),split=$('#practice-split').value,e=stage[split],t=stage.training;
 const cost=t?.total_optimizer_tensor_bytes??t?.optimizer_tensor_bytes;
 return `<p class="lab-note"><strong>${evidenceLabel()}</strong> · ${escape(report.environment.device)} · ${escape(report.environment.precision||'历史报告未单列精度')}</p><div class="practice-metrics"><div><b>${e.correct_count}/${e.sample_count}</b><span>允许格式且复制正确</span></div><div><b>${number(e.brief_rate*100,1)}%</b><span>简短且正确</span></div><div><b>${number(e.brief_target_nll,3)}</b><span>简短目标 NLL</span></div></div><div class="practice-panels"><section class="lab-output"><h2>${evidenceLabel()} · 训练过程</h2>${lossChart(t?.history)}${t?`<table class="table"><tr><th>可训练参数 ${t.critic_parameters?'（含 critic）':''}</th><td>${(t.total_trainable_parameters??t.parameters.trainable).toLocaleString()}</td></tr><tr><th>有效回答训练 token ${t.critic_parameters?'（actor）':''}</th><td>${t.effective_training_tokens.toLocaleString()}</td></tr><tr><th>${gpuRun()?'GPU 同步后的阶段耗时':'历史 CPU 阶段耗时'}</th><td>${number(t.elapsed_seconds,3)} 秒</td></tr>${gpuRun()?`<tr><th>PyTorch 阶段峰值已分配显存</th><td>${number(t.gpu_peak_allocated_bytes/1024**2,2)} MiB</td></tr><tr><th>PyTorch 阶段峰值保留显存</th><td>${number(t.gpu_peak_reserved_bytes/1024**2,2)} MiB</td></tr>`:''}<tr><th>优化器张量 ${t.critic_parameters?'（含 critic）':''}</th><td>${number(cost/1024,1)} KiB</td></tr></table>`:''}<p class="lab-note">${gpuRun()?'耗时使用 CUDA 同步前后的墙钟时间。显存峰值仅统计所选设备的 PyTorch 分配器，包含阶段开始已驻留的模型和缓存；不含 CUDA 上下文及非 PyTorch 外部库显存，不是全进程总显存或算法独占占用。':'这里是历史 CPU 耗时，不是 GPU 性能数据。'} 优化器张量大小不等于峰值内存；微型任务不足以测量大模型加速比。</p></section><section class="lab-output"><h2>与固定 SFT 参考的关系</h2><div class="formula">在同一批简短答案前缀上计算精确分布 KL</div><div class="metric-number">${number(e.kl_to_sft_on_brief_target_prefixes,4)}</div><p class="lab-note">KL 反映这些指定前缀上的分布差异，不能当成安全证明，也不是所有真实访问状态上的 KL。</p><details><summary>查看当前阶段原始训练日志</summary><pre class="practice-code">${escape(JSON.stringify(t?.history||[],null,2))}</pre></details></section></div><h2 class="practice-heading">逐条看生成结果</h2><p class="lab-note">以下是${evidenceLabel()}的全部样例。允许 <code>符号 &lt;eos&gt;</code> 或 <code>answer 符号 &lt;eos&gt;</code>；简短率只计第一种正确回答。</p><div class="table-scroll"><table class="table output-table"><thead><tr><th>输入</th><th>模型生成</th><th>判定</th></tr></thead><tbody>${e.outputs.map(row=>`<tr><td>${escape(row.prompt.join(' '))}</td><td>${escape(row.generated.join(' '))}</td><td>${row.correct?'✓ 正确':'未完成任务'}</td></tr>`).join('')}</tbody></table></div>`;
}
function fullHTML(){
 const card=report.data_card,env=report.environment;
 const hardware=gpuRun()?`${escape(env.gpu_name||env.device)} · ${number(env.gpu_total_memory_bytes/1024**3,1)} GiB · CUDA ${escape(env.cuda_runtime||'未记录')}`:`${escape(env.device)} · ${escape(env.torch_threads)} 个 CPU 线程`;
 return `<div class="notice" role="status"><strong>当前展示：${evidenceLabel()}</strong><br>${gpuRun()?`实际设备 ${escape(env.device)} · ${escape(env.gpu_name||'GPU')} · 精度 ${escape(env.precision||'未记录')}`:'当前主报告仍为历史 CPU 数据，GPU 结果尚未接入；下方曲线不能标为 GPU 实测。'}</div><section class="objectives"><h2>这次运行的设备与边界</h2><ul><li>${hardware}</li><li>${report.model_parameters.toLocaleString()} 参数 · ${report.config.layers} 层 · ${report.config.heads} 个注意力头</li><li>${card.train_rows} 条训练数据 · ${card.development_rows} 条开发探针 · ${card.final_probe_rows} 条最终探针</li><li>三个集合共享符号/意图，只留出模板组合。开发探针已参与诊断。</li><li>种子 ${report.seed} · Python ${escape(report.environment.python)} · PyTorch ${escape(report.environment.torch)}</li></ul></section><section class="prose-section"><h2>先看一条数据，怎样变成监督信号</h2><p>只做一次因果位移。当前位置预测下一 token，用户与角色标记不贡献监督 loss，答案和 EOS 参与学习。</p><details><summary>展开真实 batch 的 token / label / mask</summary><div class="table-scroll"><table class="table"><thead><tr><th>位置</th><th>输入 token</th><th>下一 token</th><th>label</th><th>计入 loss</th></tr></thead><tbody>${report.mask_walkthrough.map(x=>`<tr><td>${x.position}</td><td>${escape(x.input)}</td><td>${escape(x.next_token)}</td><td>${x.label}</td><td>${x.supervised?'是':'否'}</td></tr>`).join('')}</tbody></table></div></details></section><section class="prose-section"><h2>选择一个阶段，追问发生了什么</h2><div class="practice-selectors"><label class="field" for="practice-method"><span>训练阶段</span><select id="practice-method">${report.stages.map(s=>`<option value="${s.name}" ${s.name==='sft'?'selected':''}>${names[s.name]}</option>`).join('')}</select></label><label class="field" for="practice-split"><span>评测集合</span><select id="practice-split"><option value="evaluation">开发探针（参与过诊断）</option><option value="final_evaluation">最终探针（配方冻结后）</option></select></label></div><div id="practice-results"></div></section><section class="prose-section"><h2>为什么 loss 下降仍可能失败？</h2><p>DPO 优化相对偏好：即使 chosen 概率下降，只要 rejected 降得更多，目标仍可能改善。历史 CPU 运行出现过直接输出 EOS 的退化；当前设备上的表现应从上方实际日志与逐条回答判断，不沿用旧数字。</p><p>DPO + 辅助 SFT 加入 0.2 倍 chosen 的监督损失，用作受控修复。chosen-only SFT 与 DPO 匹配有效回答 token 预算，但更新次数不同；SimPO 使用不同归一化与目标。这些对照帮助分析原因，不构成算法排名。</p></section><section class="prose-section"><h2>奖励模型和在线奖励，分别是什么？</h2><p>本次报告包含基于 Transformer 隐藏状态的评分模型。8 个开发偏好对的排序正确率为 ${number(report.reward_model.heldout.pair_accuracy*100,1)}%，正向偏好对的 Brier 值为 ${number(report.reward_model.heldout.brier_score,4)}。如此小的诊断集合不能证明普遍校准或抗长度偏差。</p><p>PPO/GRPO 使用的是精确任务验证器：简短正确为 1，较长正确为 0.5，错误为 0。它们没有使用上述奖励模型，因此这不是已接入神经 RM 的完整 RLHF。</p></section><section class="prose-section"><h2>生成 → 筛选 → 再训练</h2>${selectionHTML()}<p>学生与教师架构相同，演示的是序列蒸馏闭环，没有展示模型压缩。所有候选都保留在完整记录中，失败候选不会被标准答案替换。</p></section><section class="prose-section"><h2>在你的 GPU 环境中复现</h2><p>按上方预检与训练命令运行，并核对报告设备、精度、源码和依赖。下载包 README 包含 GPU 安装说明；训练不下载外部模型或数据。</p><pre class="practice-code">python -m labs.tiny_lm.run --device cuda --final-eval \
  --output artifacts/tiny-lm-cuda-seed7 --seed 7

python3 labs/evaluate_measured.py</pre><p>报告的 logits 重载最大差值为 ${report.checkpoint_reload_max_logit_difference}。CPU 兼容验证须显式传入 <code>--device cpu</code>；不同设备的结果分别保留，不要求 GPU 与历史 CPU 逐位相同。保存/加载不自动证明完整在线 PPO 续训。</p><div class="button-row"><a class="btn" href="./downloads/tiny-lm/README.md" download>详细 GPU 实验说明 ↓</a><a class="btn ghost" href="#/guide/coverage">查看大纲覆盖与证据边界</a></div></section>`;
}
function selectionHTML(){const selection=report.stages.find(s=>s.name==='distill').selection;return `<p>教师先在训练侧通过 ${number(selection.gate_threshold*100,0)}% 质量门槛，实际选择 ${escape(names[selection.teacher]||selection.teacher)}。生成 ${selection.generated} 个候选，其中 ${selection.accepted} 个通过验证，按每个 prompt 第一条正确候选选中 ${selection.selected} 条训练学生。教师选择不读取开发或最终探针成绩。</p>`;}
export async function mountPractice(){
 const root=$('#practice-root');if(!root)return;
 try{if(!report){const response=await fetch('./content/tiny-lm-report.json');if(!response.ok)throw Error('report unavailable');report=await response.json();if(report.schema_version<2||!report.environment?.device||!report.stages.every(s=>s.final_evaluation))throw Error('incomplete report');}if(!root.isConnected)return;root.innerHTML=fullHTML();$('#practice-results').innerHTML=resultHTML();}
 catch{if(root.isConnected)root.innerHTML='<p role="alert">暂时无法加载实测报告。可按上方指南执行 GPU 训练，并检查 reports/tiny_lm 中的原始记录；以报告实际设备为准。</p>';}
}
document.addEventListener('change',event=>{if(['practice-method','practice-split'].includes(event.target.id)&&report&&$('#practice-results'))$('#practice-results').innerHTML=resultHTML();});
